## 4. Client-Side rpcXxxIter

### 4.1 Design

File: `internal/storage/rpc/iter_client.go` (GENERATED per type)

Key design decisions:

**Context cancellation via `rpc.Client.Go`:** `net/rpc` has no native context
support. The client uses the async `Go(...)` call and selects on `call.Done`
vs `ctx.Done()`. On context cancellation, it fires an async best-effort close
(the server will reap on idle timeout if the close RPC doesn't arrive).

**Prefetch buffer:** After each batch is consumed, `Next` fires the next
`IterXxxNext` RPC to hide latency. The batch arrives into `prefetch` while
the caller processes the current batch. On the next batch boundary, the
client swaps `current` and `prefetch`.

The prefetch is optional and controlled by `DaemonIterPrefetch` config
(default `true`). When false, `Next` fires the RPC on demand (simpler, higher
latency). The designer recommends prefetch enabled by default.

```go
// rpcIssueIter implements storage.Iter[types.Issue] over RPC.
// Generated by bddgen for the IterIssues method.
type rpcIssueIter struct {
    client    *rpc.Client
    sessionID string
    batchSize int

    // current batch state
    batch []*types.Issue
    pos   int  // 0-based; current item is batch[pos] after advance

    // prefetch state (non-nil when a prefetch RPC is in flight)
    prefetchCall *rpc.Call
    prefetchReply *IterIssuesNextReply

    done   bool
    err    error
    closed bool
    mu     sync.Mutex // guards closed
}

func (it *rpcIssueIter) Next(ctx context.Context) bool {
    if it.closed || it.done || it.err != nil {
        return false
    }

    it.pos++

    // Serve from current batch if rows remain
    if it.pos <= len(it.batch) {
        // Fire prefetch when we reach the last item in the batch
        if it.pos == len(it.batch) && it.prefetchCall == nil {
            it.firePrefetch()
        }
        return true
    }

    // Current batch exhausted — collect prefetch (or fire synchronously)
    return it.fetchNextBatch(ctx)
}

func (it *rpcIssueIter) firePrefetch() {
    it.prefetchReply = &IterIssuesNextReply{}
    it.prefetchCall = it.client.Go(
        "DaemonServer.IterIssuesNext",
        &IterNextArgs{SessionID: it.sessionID, BatchSize: it.batchSize},
        it.prefetchReply,
        nil,
    )
}

func (it *rpcIssueIter) fetchNextBatch(ctx context.Context) bool {
    var reply *IterIssuesNextReply

    if it.prefetchCall != nil {
        // Collect the in-flight prefetch, respecting context cancellation
        select {
        case <-ctx.Done():
            it.err = ctx.Err()
            go it.closeAsync() // best-effort server cleanup
            return false
        case <-it.prefetchCall.Done:
            if it.prefetchCall.Error != nil {
                it.err = it.prefetchCall.Error
                return false
            }
            reply = it.prefetchReply
            it.prefetchCall = nil
            it.prefetchReply = nil
        }
    } else {
        // No prefetch in flight: fire synchronously with ctx support
        reply = &IterIssuesNextReply{}
        call := it.client.Go(
            "DaemonServer.IterIssuesNext",
            &IterNextArgs{SessionID: it.sessionID, BatchSize: it.batchSize},
            reply,
            nil,
        )
        select {
        case <-ctx.Done():
            it.err = ctx.Err()
            go it.closeAsync()
            return false
        case <-call.Done:
            if call.Error != nil {
                it.err = call.Error
                return false
            }
        }
    }

    if reply.RPCError != nil {
        it.err = decodeRPCError(reply.RPCError)
        return false
    }
    if reply.Done || len(reply.Issues) == 0 {
        it.done = true
        return false
    }

    it.batch = reply.Issues
    it.pos = 1
    // Fire next prefetch if batch is small enough to anticipate exhaustion
    if len(it.batch) >= it.batchSize && it.prefetchCall == nil {
        it.firePrefetch()
    }
    return true
}

func (it *rpcIssueIter) Value() *types.Issue {
    if it.pos < 1 || it.pos > len(it.batch) {
        return nil
    }
    return it.batch[it.pos-1]
}

func (it *rpcIssueIter) Err() error { return it.err }

func (it *rpcIssueIter) Close() error {
    it.mu.Lock()
    if it.closed {
        it.mu.Unlock()
        return nil
    }
    it.closed = true
    it.mu.Unlock()

    reply := &IterCloseReply{}
    err := it.client.Call(
        "DaemonServer.IterClose",
        &IterCloseArgs{SessionID: it.sessionID},
        reply,
    )
    if err != nil {
        return fmt.Errorf("rpc IterClose: %w", err)
    }
    return decodeRPCError(reply.RPCError)
}

func (it *rpcIssueIter) closeAsync() {
    reply := &IterCloseReply{}
    _ = it.client.Call(
        "DaemonServer.IterClose",
        &IterCloseArgs{SessionID: it.sessionID},
        reply,
    )
}
```

### 4.2 Client fallback on ErrTooManyIterators

`daemonClient.IterIssues` checks the reply error and falls back to the Phase 1
slice path on `ErrTooManyIterators`:

```go
func (c *daemonClient) IterIssues(ctx context.Context, query string, filter types.IssueFilter) (storage.Iter[types.Issue], error) {
    batchSize := c.cfg.GetDaemonIterBatch()
    reply := &IterStartReply{}
    if err := c.rpcClient.Call("DaemonServer.IterIssuesStart",
        &IterIssuesStartArgs{Query: query, Filter: filter, BatchSize: batchSize},
        reply); err != nil {
        return nil, fmt.Errorf("rpc IterIssues start: %w", err)
    }
    if reply.RPCError != nil {
        decoded := decodeRPCError(reply.RPCError)
        if errors.Is(decoded, storage.ErrTooManyIterators) {
            // Warn and fall back to slice path
            log.Printf("[bdd] warning: iterator cap reached, falling back to slice path for IterIssues")
            issues, err := c.SearchIssues(ctx, query, filter)
            if err != nil {
                return nil, err
            }
            return storage.NewSliceIter(issues), nil
        }
        return nil, decoded
    }
    return &rpcIssueIter{
        client:    c.rpcClient,
        sessionID: reply.SessionID,
        batchSize: batchSize,
    }, nil
}
```

