## 5. Server-Side `IterXxxStart` and `IterXxxNext` Methods

File: `internal/storage/rpc/iter_server.go` (GENERATED)

Example for IterIssues:

```go
func (s *daemonServer) IterIssuesStart(args *IterIssuesStartArgs, reply *IterStartReply) error {
    batchSize := args.BatchSize
    if batchSize <= 0 {
        batchSize = s.cfg.GetDaemonIterBatch()
    }

    // Open underlying iterator — uses the daemon's own ctx
    iter, err := s.store.IterIssues(s.ctx, args.Query, args.Filter)
    if err != nil {
        reply.RPCError = encodeRPCError(err)
        return nil
    }

    sessionID := newUUIDv4()
    sessCtx, cancel := context.WithCancel(s.ctx)
    sess := &issueIterSession{
        iter:      iter,
        ctx:       sessCtx,
        cancel:    cancel,
        typeName:  "issues",
        batchSize: batchSize,
    }
    sess.Touch()
    atomic.StoreInt64(&sess.lastUsed, time.Now().UnixNano())

    if err := s.iterMgr.openSession(sessionID, sess); err != nil {
        cancel()
        iter.Close()
        reply.RPCError = encodeRPCError(err) // ErrTooManyIterators
        return nil
    }

    reply.SessionID = sessionID
    return nil
}

func (s *daemonServer) IterIssuesNext(args *IterNextArgs, reply *IterIssuesNextReply) error {
    sess, ok := s.iterMgr.getSession(args.SessionID)
    if !ok {
        reply.RPCError = encodeRPCError(storage.ErrIterSessionNotFound)
        return nil
    }
    issueSess, ok := sess.(*issueIterSession)
    if !ok {
        // Session type mismatch — shouldn't happen if client is well-behaved
        reply.RPCError = encodeRPCError(fmt.Errorf("session %s is not an issue iterator", args.SessionID))
        return nil
    }

    batchSize := args.BatchSize
    if batchSize <= 0 {
        batchSize = issueSess.batchSize
    }

    // Serialize concurrent Next calls for the same session
    issueSess.mu.Lock()
    defer issueSess.mu.Unlock()
    issueSess.Touch()

    var batch []*types.Issue
    for i := 0; i < batchSize; i++ {
        if !issueSess.iter.Next(issueSess.ctx) {
            if err := issueSess.iter.Err(); err != nil {
                reply.RPCError = encodeRPCError(err)
                s.iterMgr.closeSession(args.SessionID) // release session on error
                return nil
            }
            reply.Done = true
            break
        }
        // Value() may return a pointer reused on next Next() — copy it
        v := *issueSess.iter.Value()
        batch = append(batch, &v)
        s.iterMgr.stats.rowsStreamedTotal.Add(1)
    }

    if reply.Done {
        s.iterMgr.closeSession(args.SessionID) // auto-close on exhaustion
    }

    reply.Issues = batch
    return nil
}

func (s *daemonServer) IterClose(args *IterCloseArgs, reply *IterCloseReply) error {
    s.iterMgr.closeSession(args.SessionID)
    // Not an error if session doesn't exist (idempotent close is safe)
    return nil
}
```

**Value copy note:** `Iter[T].Value()` documents that the pointer "may be
reused" across `Next()` calls (be-jaavsb §2). The server copies the value
before appending to the batch to ensure the batch slice remains valid after
the next `Next()` call.

